package com.crystaln.vpn.data

import org.json.JSONObject
import java.io.File

/**
 * Desktop settings (JSON file in the config dir). A subset of the Android
 * app's settings that makes sense off-phone; theme is handled by the OS and
 * the Compose theme.
 */
object SettingsStore {

    enum class ThemeMode { SYSTEM, LIGHT, DARK }

    private const val FILE = "settings.json"

    private val lock = Any()

    @Volatile
    private var cache: JSONObject? = null

    @Volatile
    private var loadedDir: File? = null

    internal fun resetForTest() {
        synchronized(lock) {
            cache = null
            loadedDir = null
        }
    }

    private fun file(dataDir: File) = File(dataDir, FILE)

    private fun load(dataDir: File): JSONObject = synchronized(lock) {
        if (cache != null && loadedDir == dataDir) return cache as JSONObject
        val o = try {
            val f = file(dataDir)
            if (f.exists()) JSONObject(f.readText()) else JSONObject()
        } catch (_: Exception) {
            JSONObject()
        }
        cache = o
        loadedDir = dataDir
        o
    }

    private fun save(dataDir: File, o: JSONObject) {
        dataDir.mkdirs()
        val f = file(dataDir)
        val tmp = File(dataDir, "$FILE.tmp")
        try {
            com.crystaln.vpn.desktop.net.SecureFiles.writeText(tmp, o.toString(2))
            if (!tmp.renameTo(f)) {
                com.crystaln.vpn.desktop.net.SecureFiles.writeText(f, o.toString(2))
                tmp.delete()
            }
        } catch (_: Exception) {
            tmp.delete()
        }
    }

    private fun mutate(dataDir: File, block: (JSONObject) -> Unit) = synchronized(lock) {
        val o = load(dataDir)
        block(o)
        save(dataDir, o)
    }

    // ── connection behavior ──────────────────────────────────────────────

    /** Connect the selected profile automatically on app launch. */
    fun autoConnect(dataDir: File): Boolean = load(dataDir).optBoolean("autoConnect", false)

    fun setAutoConnect(dataDir: File, v: Boolean) = mutate(dataDir) { it.put("autoConnect", v) }

    /** Local proxy ports for the no-root mode. */
    fun socksPort(dataDir: File): Int = load(dataDir).optInt("socksPort", 10808)

    fun setSocksPort(dataDir: File, v: Int) = mutate(dataDir) { it.put("socksPort", v.coerceIn(1024, 65535)) }

    fun httpPort(dataDir: File): Int = load(dataDir).optInt("httpPort", 10809)

    fun setHttpPort(dataDir: File, v: Int) = mutate(dataDir) { it.put("httpPort", v.coerceIn(1024, 65535)) }

    /** Anti-leak: intercept DNS inside the TUN and resolve via the tunnel. */
    fun dnsViaTunnel(dataDir: File): Boolean = load(dataDir).optBoolean("dnsViaTunnel", false)

    fun setDnsViaTunnel(dataDir: File, v: Boolean) = mutate(dataDir) { it.put("dnsViaTunnel", v) }

    fun dnsServer(dataDir: File): String = load(dataDir).optString("dnsServer", "1.1.1.1")

    fun setDnsServer(dataDir: File, v: String) = mutate(dataDir) { it.put("dnsServer", v.trim()) }

    /** Drop ad/tracker domains (needs geosite.dat next to the xray binary). */
    fun blockAds(dataDir: File): Boolean = load(dataDir).optBoolean("blockAds", false)

    fun setBlockAds(dataDir: File, v: Boolean) = mutate(dataDir) { it.put("blockAds", v) }

    fun anonymizeNames(dataDir: File): Boolean = load(dataDir).optBoolean("anonymizeNames", false)

    fun setAnonymizeNames(dataDir: File, v: Boolean) = mutate(dataDir) { it.put("anonymizeNames", v) }

    /** URL probed through the tunnel to confirm the connection is live. */
    fun checkUrl(dataDir: File): String =
        load(dataDir).optString("checkUrl", "https://www.gstatic.com/generate_204")

    fun setCheckUrl(dataDir: File, v: String) {
        val u = v.trim()
        if (u.startsWith("http://", true) || u.startsWith("https://", true)) {
            mutate(dataDir) { it.put("checkUrl", u) }
        }
    }

    /** Seconds allowed for the connection test before declaring failure. */
    fun checkTimeoutSec(dataDir: File): Int = load(dataDir).optInt("checkTimeoutSec", 15).coerceIn(3, 60)

    fun setCheckTimeoutSec(dataDir: File, v: Int) =
        mutate(dataDir) { it.put("checkTimeoutSec", v.coerceIn(3, 60)) }

    /** Reconnect automatically after an unexpected tunnel drop. */
    fun autoReconnect(dataDir: File): Boolean = load(dataDir).optBoolean("autoReconnect", false)

    fun setAutoReconnect(dataDir: File, v: Boolean) = mutate(dataDir) { it.put("autoReconnect", v) }

    /** Profile used as fallback after auto-reconnect attempts are exhausted. */
    fun fallbackProfileId(dataDir: File): String? = load(dataDir).optString("fallbackProfileId").ifEmpty { null }

    fun setFallbackProfileId(dataDir: File, id: String?) =
        mutate(dataDir) {
            if (id == null) it.remove("fallbackProfileId") else it.put("fallbackProfileId", id)
        }

    /**
     * Kill-switch: when the tunnel drops unexpectedly, block all non-loopback
     * traffic until the user disconnects/reconnects (or the app restarts).
     * Implemented with platform firewall rules applied by the privileged
     * helper; never enabled for the plain local-proxy mode.
     */
    fun killSwitch(dataDir: File): Boolean = load(dataDir).optBoolean("killSwitch", false)

    fun setKillSwitch(dataDir: File, v: Boolean) = mutate(dataDir) { it.put("killSwitch", v) }

    /** Default tunnel mode for Xray-family profiles. */
    enum class TunnelMode { TUN, PROXY }

    fun tunnelMode(dataDir: File): TunnelMode =
        if (load(dataDir).optString("tunnelMode") == "PROXY") TunnelMode.PROXY else TunnelMode.TUN

    fun setTunnelMode(dataDir: File, m: TunnelMode) =
        mutate(dataDir) { it.put("tunnelMode", m.name) }

    // ── appearance (parity with the Android app) ─────────────────────────

    fun themeMode(dataDir: File): ThemeMode = when (load(dataDir).optString("themeMode")) {
        "LIGHT" -> ThemeMode.LIGHT
        "DARK" -> ThemeMode.DARK
        else -> ThemeMode.SYSTEM
    }

    fun setThemeMode(dataDir: File, m: ThemeMode) = mutate(dataDir) { it.put("themeMode", m.name) }

    fun paletteId(dataDir: File): String = load(dataDir).optString("palette").ifEmpty { "indigo" }

    fun setPaletteId(dataDir: File, id: String) = mutate(dataDir) { it.put("palette", id) }

    /** Before connecting, ping all servers and pick the fastest alive one. */
    /** First-run wizard completed (or explicitly skipped). */
    fun onboarded(dataDir: File): Boolean = load(dataDir).optBoolean("onboarded", false)

    fun setOnboarded(dataDir: File, v: Boolean) = mutate(dataDir) { it.put("onboarded", v) }

    fun autoFastest(dataDir: File): Boolean = load(dataDir).optBoolean("autoFastest", false)

    fun setAutoFastest(dataDir: File, v: Boolean) = mutate(dataDir) { it.put("autoFastest", v) }

    /**
     * Автозагрузка при входе в систему (Windows: HKCU Run, Linux: XDG
     * autostart). Путь к бинарнику машино-специфичен — в backup не экспортируется.
     */
    fun startWithSystem(dataDir: File): Boolean = load(dataDir).optBoolean("startWithSystem", false)

    fun setStartWithSystem(dataDir: File, v: Boolean) =
        mutate(dataDir) { it.put("startWithSystem", v) }

    /** Everything restorable from a crystaln/2 backup (plus desktop-only extras). */
    fun exportJson(dataDir: File): JSONObject = JSONObject()
        .put("themeMode", themeMode(dataDir).name)
        .put("palette", paletteId(dataDir))
        .put("autoConnect", autoConnect(dataDir))
        .put("autoFastest", autoFastest(dataDir))
        .put("dnsViaTunnel", dnsViaTunnel(dataDir))
        .put("dnsServer", dnsServer(dataDir))
        .put("blockAds", blockAds(dataDir))
        .put("anonymizeNames", anonymizeNames(dataDir))
        .put("checkUrl", checkUrl(dataDir))
        .put("checkTimeoutSec", checkTimeoutSec(dataDir))
        .put("autoReconnect", autoReconnect(dataDir))
        .put("fallbackProfileId", fallbackProfileId(dataDir) ?: "")
        .put("killSwitch", killSwitch(dataDir))
        .put("socksPort", socksPort(dataDir))
        .put("httpPort", httpPort(dataDir))
        .put("tunnelMode", tunnelMode(dataDir).name)

    fun importJson(dataDir: File, o: JSONObject) {
        mutate(dataDir) { store ->
            when (o.optString("themeMode")) {
                "LIGHT" -> store.put("themeMode", "LIGHT")
                "DARK" -> store.put("themeMode", "DARK")
                "SYSTEM" -> store.put("themeMode", "SYSTEM")
            }
            o.optString("palette").takeIf { it.isNotEmpty() }?.let { store.put("palette", it) }
            store.put("autoConnect", o.optBoolean("autoConnect", false))
            store.put("autoFastest", o.optBoolean("autoFastest", false))
            store.put("dnsViaTunnel", o.optBoolean("dnsViaTunnel", false))
            o.optString("dnsServer").takeIf { it.isNotEmpty() }?.let { store.put("dnsServer", it) }
            store.put("blockAds", o.optBoolean("blockAds", false))
            store.put("anonymizeNames", o.optBoolean("anonymizeNames", false))
            o.optString("checkUrl").takeIf { it.isNotEmpty() }?.let { store.put("checkUrl", it) }
            if (o.has("checkTimeoutSec")) store.put("checkTimeoutSec", o.optInt("checkTimeoutSec", 15).coerceIn(3, 60))
            store.put("autoReconnect", o.optBoolean("autoReconnect", false))
            o.optString("fallbackProfileId").takeIf { it.isNotEmpty() }?.let { store.put("fallbackProfileId", it) }
            store.put("killSwitch", o.optBoolean("killSwitch", false))
            if (o.has("socksPort")) store.put("socksPort", o.optInt("socksPort", 10808).coerceIn(1024, 65535))
            if (o.has("httpPort")) store.put("httpPort", o.optInt("httpPort", 10809).coerceIn(1024, 65535))
        }
    }
}

package com.crystaln.vpn.data

import org.json.JSONObject
import java.io.File

/** Accumulated usage counters for one profile. */
data class TrafficStats(
    val rx: Long = 0,
    val tx: Long = 0,
    /** Total seconds the tunnel ran with this profile. */
    val seconds: Long = 0,
)

/**
 * JSON-file backed per-profile usage totals. Desktop port of the Android
 * store: the 1 Hz poller in [com.crystaln.vpn.desktop.net.TunnelManager] adds
 * session deltas here; saves are debounced so the file is written at most
 * once a minute plus once on session end, never per tick.
 */
object TrafficStatsStore {
    private const val FILE = "traffic_stats.json"
    private const val SAVE_PERIOD_TICKS = 60 // 1 Hz poller → once a minute

    private val lock = Any()
    private val stats = HashMap<String, TrafficStats>()
    private var ticksSinceSave = 0
    private var loadedDir: File? = null

    /** Test-only hook: forgets the in-memory cache so a fresh dir reloads. */
    internal fun resetForTest() {
        synchronized(lock) {
            stats.clear()
            ticksSinceSave = 0
            loadedDir = null
        }
    }

    private fun loadIfNeeded(dataDir: File) {
        if (loadedDir == dataDir) return
        loadedDir = dataDir
        val f = File(dataDir, FILE)
        if (!f.exists()) return
        try {
            val root = JSONObject(f.readText())
            root.keys().forEach { id ->
                val o = root.getJSONObject(id)
                stats[id] = TrafficStats(
                    rx = o.optLong("rx"),
                    tx = o.optLong("tx"),
                    seconds = o.optLong("seconds"),
                )
            }
        } catch (_: Exception) {
            // Corrupt stats are disposable usage counters, not user data.
        }
    }

    fun all(dataDir: File): Map<String, TrafficStats> = synchronized(lock) {
        loadIfNeeded(dataDir)
        stats.toMap()
    }

    /**
     * Adds byte counters for [profileId]; caller supplies the delta it
     * measured. Returns the accumulated total after the update.
     */
    fun add(
        dataDir: File,
        profileId: String,
        rx: Long,
        tx: Long,
        seconds: Long = 0,
    ): Unit = synchronized(lock) {
        if (rx <= 0 && tx <= 0 && seconds <= 0) return
        loadIfNeeded(dataDir)
        val old = stats[profileId] ?: TrafficStats()
        stats[profileId] = TrafficStats(
            rx = old.rx + rx,
            tx = old.tx + tx,
            seconds = old.seconds + seconds,
        )
        if (++ticksSinceSave >= SAVE_PERIOD_TICKS) save(dataDir)
    }

    fun get(dataDir: File, profileId: String): TrafficStats = synchronized(lock) {
        loadIfNeeded(dataDir)
        stats[profileId] ?: TrafficStats()
    }

    fun clear(dataDir: File, profileId: String): Unit = synchronized(lock) {
        loadIfNeeded(dataDir)
        stats.remove(profileId)
        save(dataDir)
    }

    /** Writes pending counters immediately (session end). */
    fun flush(dataDir: File): Unit = synchronized(lock) {
        loadIfNeeded(dataDir)
        save(dataDir)
    }

    private fun save(dataDir: File) {
        ticksSinceSave = 0
        val root = JSONObject()
        stats.forEach { (id, s) ->
            root.put(id, JSONObject().put("rx", s.rx).put("tx", s.tx).put("seconds", s.seconds))
        }
        dataDir.mkdirs()
        val f = File(dataDir, FILE)
        val tmp = File(dataDir, "$FILE.tmp")
        try {
            tmp.writeText(root.toString())
            if (!tmp.renameTo(f)) {
                f.writeText(root.toString())
                tmp.delete()
            }
        } catch (_: Exception) {
            tmp.delete()
        }
    }
}

package com.crystaln.vpn.data

import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/**
 * Full backup ("settings + subscriptions + profiles"), format crystaln/2.
 * Desktop port of the Android file: [File] data dir instead of a Context,
 * same JSON formats — Android and desktop backups are interchangeable.
 *
 * The old crystaln/1 export kept only profiles; the same vault encryption
 * (see [ProfileVault]) wraps this payload, so a password-protected backup
 * now restores the whole app configuration, not just servers.
 */
object Backup {

    /** Profile-only exports stay crystaln/1; this is the superset. */
    fun exportFull(dataDir: File): String = JSONObject()
        .put("format", "crystaln/2")
        .put("selected", ProfileStore.selectedId ?: "")
        .put(
            "profiles",
            JSONArray().apply { ProfileStore.load(dataDir).forEach { put(it.toJson()) } },
        )
        .put("subscriptions", SubscriptionsStore.exportJson(dataDir))
        .put("settings", SettingsStore.exportJson(dataDir))
        .toString(2)

    /**
     * Imports a crystaln/2 backup: settings first, then subscriptions, then
     * profiles (via the normal merge — re-imports update in place). Returns
     * a user-facing summary, or null when the text is not a crystaln/2 backup
     * (caller falls back to the profile-only import path).
     */
    fun importFull(dataDir: File, text: String): String? {
        val root = try {
            JSONObject(text.trim())
        } catch (_: Exception) {
            return null
        }
        if (root.optString("format") != "crystaln/2") return null

        root.optJSONObject("settings")?.let { SettingsStore.importJson(dataDir, it) }
        val subs = root.optJSONArray("subscriptions")
            ?.let { SubscriptionsStore.importJson(dataDir, it) } ?: 0

        // Profiles ride the existing crystaln/1 merge path (dedupe + selection).
        val parsed = ProfileImporter.parseText(text)
        val merged = if (parsed.isNotEmpty()) {
            ProfileStore.mergeProfiles(dataDir, parsed, subscriptionId = null, selectFirst = true)
        } else null

        return buildString {
            if (merged != null) {
                append("Профили: ${merged.added + merged.updated}")
            }
            if (subs > 0) {
                if (isNotEmpty()) append(" · ")
                append("Подписки: $subs")
            }
            if (isEmpty()) append("Настройки восстановлены")
        }
    }
}

package com.crystaln.vpn.xray

import com.crystaln.vpn.data.Profile
import com.crystaln.vpn.data.Protocol
import org.json.JSONArray
import org.json.JSONObject

/**
 * Builds a full Xray-core config with a TUN inbound for [Profile]s of the
 * Xray family (VMess, VLESS, Trojan, Shadowsocks, SOCKS, HTTP).
 *
 * The TUN inbound is fed the VPN interface fd by the service; sniffing is on so
 * domain routing works even when clients connect by IP.
 */
object XrayConfigBuilder {

    const val TUN_MTU = 8500

    /** Options that tune the config without changing the server. */
    data class Options(
        /** Intercept port 53 in the TUN and resolve DNS through the tunnel. */
        val dnsViaTunnel: Boolean = false,
        /** Upstream DNS server used when [dnsViaTunnel] is on. */
        val dnsServer: String = "1.1.1.1",
        /** Drop ad/tracker domains (geosite:category-ads-all → block). */
        val blockAds: Boolean = false,
    )

    fun build(profile: Profile): String = build(profile, Options())

    fun build(profile: Profile, options: Options): String {
        val root = JSONObject()
        root.put("log", JSONObject().put("loglevel", "warning"))
        root.put("inbounds", JSONArray().put(tunInbound()))
        root.put("outbounds", JSONArray().apply {
            put(buildOutbound(profile))
            put(directOutbound())
            put(blockOutbound())
            if (options.dnsViaTunnel) put(dnsOutbound(options.dnsServer))
        })
        root.put("routing", routing(options))
        return root.toString()
    }

    /**
     * Desktop proxy-mode config: local SOCKS/HTTP inbounds instead of the TUN.
     * The desktop xray-core binary has no `tun` inbound (that inbound is an
     * AndroidLibXrayLite addition), so TUN mode is built on top of this same
     * local proxy by tun2socks (see XrayRunner).
     */
    fun buildProxy(
        profile: Profile,
        options: Options,
        socksPort: Int,
        httpPort: Int,
    ): String {
        val root = JSONObject()
        root.put("log", JSONObject().put("loglevel", "warning"))
        root.put("inbounds", JSONArray().apply {
            put(
                JSONObject().apply {
                    put("tag", "socks-in")
                    put("listen", "127.0.0.1")
                    put("port", socksPort)
                    put("protocol", "socks")
                    put("settings", JSONObject().put("udp", true))
                },
            )
            if (httpPort > 0) {
                put(
                    JSONObject().apply {
                        put("tag", "http-in")
                        put("listen", "127.0.0.1")
                        put("port", httpPort)
                        put("protocol", "http")
                        put("settings", JSONObject())
                    },
                )
            }
        })
        root.put("outbounds", JSONArray().apply {
            put(buildOutbound(profile))
            put(directOutbound())
            put(blockOutbound())
            if (options.dnsViaTunnel) put(dnsOutbound(options.dnsServer))
        })
        root.put("routing", routing(options))
        return root.toString()
    }

    private fun tunInbound(): JSONObject = JSONObject().apply {
        put("tag", "tun")
        put("protocol", "tun")
        put(
            "settings",
            JSONObject().put("name", "xray0").put("MTU", TUN_MTU).put("userLevel", 8),
        )
        put(
            "sniffing",
            JSONObject().put("enabled", true)
                .put("destOverride", JSONArray().put("http").put("tls").put("quic")),
        )
    }

    private fun routing(options: Options): JSONObject = JSONObject().apply {
        put("domainStrategy", "IPIfNonMatch")
        put(
            "rules",
            JSONArray().apply {
                // Local/loopback/link-local traffic stays off the tunnel.
                put(
                    JSONObject().put(
                        "ip",
                        JSONArray()
                            .put("10.0.0.0/8").put("172.16.0.0/12").put("192.168.0.0/16")
                            .put("127.0.0.0/8").put("169.254.0.0/16").put("100.64.0.0/10")
                            .put("fe80::/10").put("fc00::/7"),
                    ).put("outboundTag", "direct"),
                )
                // Ads/tracker domains die before they leave the device.
                if (options.blockAds) {
                    put(
                        JSONObject()
                            .put("domain", JSONArray().put("geosite:category-ads-all"))
                            .put("outboundTag", "block"),
                    )
                }
                // Plain DNS (port 53) goes through the tunnel's dns-out instead
                // of leaking to the local network / ISP resolver. Must precede
                // the catch-all proxy rule.
                if (options.dnsViaTunnel) {
                    put(
                        JSONObject()
                            .put("port", "53")
                            .put("network", "udp,tcp")
                            .put("outboundTag", "dns-out"),
                    )
                }
            },
        )
    }

    /** DNS forwarded to [server] through the proxy outbound. */
    private fun dnsOutbound(server: String): JSONObject = JSONObject().apply {
        put("tag", "dns-out")
        put("protocol", "dns")
        put(
            "settings",
            JSONObject().apply {
                if (server.isNotEmpty()) put("address", server)
                put("port", 53)
            },
        )
    }

    private fun directOutbound(): JSONObject = JSONObject().apply {
        put("tag", "direct")
        put("protocol", "freedom")
        put("settings", JSONObject())
    }

    private fun blockOutbound(): JSONObject = JSONObject().apply {
        put("tag", "block")
        put("protocol", "blackhole")
        put("settings", JSONObject())
    }

    /**
     * Local SOCKS5 port of the Hysteria2 core (child process). For HYSTERIA2
     * profiles the xray outbound is a SOCKS proxy pointing at the hysteria
     * binary listening on this loopback port — hysteria speaks QUIC to the
     * real server.
     */
    const val HYSTERIA_SOCKS_PORT = 17901

    /** Local mixed (SOCKS5+HTTP) port of the sing-box core (TUIC/AnyTLS/Hysteria v1). */
    const val SINGBOX_MIXED_PORT = 17902

    fun buildOutbound(profile: Profile): JSONObject = when {
        profile.isHysteria -> JSONObject().apply {
            put("tag", "proxy")
            put("protocol", "socks")
            put(
                "settings",
                JSONObject().put(
                    "servers",
                    JSONArray().put(
                        JSONObject()
                            .put("address", "127.0.0.1")
                            .put("port", HYSTERIA_SOCKS_PORT),
                    ),
                ),
            )
        }

        profile.isSingBoxFamily -> JSONObject().apply {
            put("tag", "proxy")
            put("protocol", "socks")
            put(
                "settings",
                JSONObject().put(
                    "servers",
                    JSONArray().put(
                        JSONObject()
                            .put("address", "127.0.0.1")
                            .put("port", SINGBOX_MIXED_PORT),
                    ),
                ),
            )
        }

        else -> JSONObject().apply {
            put("tag", "proxy")
            put("protocol", xrayProtocol(profile.protocol))
            put("settings", settingsFor(profile))
            val stream = streamSettings(profile)
            if (stream != null) put("streamSettings", stream)
        }
    }

    private fun xrayProtocol(p: Protocol): String = when (p) {
        Protocol.VMESS -> "vmess"
        Protocol.VLESS -> "vless"
        Protocol.TROJAN -> "trojan"
        Protocol.SHADOWSOCKS -> "shadowsocks"
        Protocol.SOCKS -> "socks"
        Protocol.HTTP, Protocol.HTTPS -> "http"
        Protocol.WIREGUARD, Protocol.AMNEZIAWG ->
            throw IllegalArgumentException("WireGuard-family is not routed through Xray")
        Protocol.OPENVPN ->
            throw IllegalArgumentException("OpenVPN is not routed through Xray")
        Protocol.HYSTERIA2 ->
            throw IllegalArgumentException("Hysteria2 is routed through its own SOCKS outbound")
        Protocol.TUIC ->
            throw IllegalArgumentException("TUIC requires the sing-box engine (planned)")
        Protocol.ANYTLS, Protocol.HYSTERIA1 ->
            throw IllegalArgumentException("AnyTLS/Hysteria v1 require the sing-box engine (planned)")
    }

    private fun settingsFor(p: Profile): JSONObject = when (p.protocol) {
        Protocol.VMESS -> JSONObject().put(
            "vnext",
            JSONArray().put(
                server(p).put(
                    "users",
                    JSONArray().put(
                        JSONObject()
                            .put("id", p.fields["uuid"] ?: "")
                            .put("alterId", (p.fields["alterId"] ?: "0").toIntOrNull() ?: 0)
                            .put("security", p.fields["security"] ?: "auto")
                            .put("level", 8),
                    ),
                ),
            ),
        )

        Protocol.VLESS -> JSONObject().put(
            "vnext",
            JSONArray().put(
                server(p).put(
                    "users",
                    JSONArray().put(
                        JSONObject().apply {
                            put("id", p.fields["uuid"] ?: "")
                            put("encryption", "none")
                            put("level", 8)
                            p.fields["flow"]?.takeIf { it.isNotEmpty() }?.let { put("flow", it) }
                        },
                    ),
                ),
            ),
        )

        Protocol.TROJAN -> JSONObject().put(
            "servers",
            JSONArray().put(
                server(p).apply {
                    put("password", p.fields["password"] ?: "")
                },
            ),
        )

        Protocol.SHADOWSOCKS -> JSONObject().put(
            "servers",
            JSONArray().put(
                server(p).apply {
                    put("method", p.fields["method"] ?: "aes-256-gcm")
                    put("password", p.fields["password"] ?: "")
                    put("uot", true)
                },
            ),
        )

        Protocol.SOCKS, Protocol.HTTP, Protocol.HTTPS -> JSONObject().put(
            "servers",
            JSONArray().put(
                server(p).apply {
                    val user = p.fields["username"]
                    val pass = p.fields["password"]
                    if (!user.isNullOrEmpty()) {
                        put(
                            "users",
                            JSONArray().put(
                                JSONObject().put("user", user).put("pass", pass ?: "").put("level", 8),
                            ),
                        )
                    }
                },
            ),
        )

        Protocol.WIREGUARD, Protocol.AMNEZIAWG ->
            throw IllegalArgumentException("WireGuard-family is not routed through Xray")

        Protocol.OPENVPN ->
            throw IllegalArgumentException("OpenVPN is not routed through Xray")

        Protocol.HYSTERIA2 ->
            throw IllegalArgumentException("Hysteria2 is routed through its own SOCKS outbound")
        Protocol.TUIC ->
            throw IllegalArgumentException("TUIC requires the sing-box engine (planned)")
        Protocol.ANYTLS, Protocol.HYSTERIA1 ->
            throw IllegalArgumentException("AnyTLS/Hysteria v1 require the sing-box engine (planned)")
    }

    private fun server(p: Profile): JSONObject =
        JSONObject().put("address", p.address).put("port", p.port)

    private fun streamSettings(p: Profile): JSONObject? {
        val network = p.fields["network"] ?: "tcp"
        val s = JSONObject().put("network", network)
        when (network) {
            "ws" -> s.put(
                "wsSettings",
                JSONObject().apply {
                    put("path", p.fields["path"] ?: "/")
                    p.fields["host"]?.takeIf { it.isNotEmpty() }?.let {
                        put("headers", JSONObject().put("Host", it))
                    }
                },
            )

            "grpc" -> s.put(
                "grpcSettings",
                JSONObject().apply {
                    put("serviceName", p.fields["serviceName"] ?: "")
                    put("multiMode", (p.fields["multiMode"] ?: "false") == "true")
                },
            )

            "httpupgrade" -> s.put(
                "httpupgradeSettings",
                JSONObject().apply {
                    put("path", p.fields["path"] ?: "/")
                    put("host", p.fields["host"] ?: "")
                },
            )

            "xhttp", "splithttp" -> s.put(
                "xhttpSettings",
                JSONObject().apply {
                    put("path", p.fields["path"] ?: "/")
                    put("host", p.fields["host"] ?: "")
                    p.fields["mode"]?.takeIf { it.isNotEmpty() }?.let { put("mode", it) }
                },
            )

            "kcp" -> s.put(
                "kcpSettings",
                JSONObject().apply {
                    put("mtu", 1350)
                    put("tti", 50)
                    put("uplinkCapacity", 12)
                    put("downlinkCapacity", 100)
                    put("congestion", false)
                    put("readBufferSize", 1)
                    put("writeBufferSize", 1)
                    put(
                        "header",
                        JSONObject().put("type", p.fields["headerType"] ?: "none"),
                    )
                    p.fields["kcpSeed"]?.takeIf { it.isNotEmpty() }?.let { put("seed", it) }
                },
            )

            "quic" -> s.put(
                "quicSettings",
                JSONObject().apply {
                    put("security", p.fields["quicSecurity"] ?: "none")
                    put("key", p.fields["quicKey"] ?: "")
                    put("header", JSONObject().put("type", p.fields["headerType"] ?: "none"))
                },
            )

            "http", "h2" -> s.put(
                "httpSettings",
                JSONObject().apply {
                    put("path", p.fields["path"] ?: "/")
                    val host = p.fields["host"]
                    if (!host.isNullOrEmpty()) {
                        put("host", JSONArray().put(host))
                    }
                },
            )

            else -> {} // tcp
        }

        val useTls = p.fields["tls"] == "true" || p.protocol == Protocol.HTTPS
        val useReality = p.fields["reality"] == "true"
        if (useTls || useReality) {
            s.put("security", if (useReality) "reality" else "tls")
            if (useReality) {
                s.put(
                    "realitySettings",
                    JSONObject().apply {
                        put("show", false)
                        put("fingerprint", p.fields["fingerprint"] ?: "chrome")
                        put("serverName", p.fields["sni"] ?: "")
                        put("publicKey", p.fields["publicKey"] ?: "")
                        put("shortId", p.fields["shortId"] ?: "")
                        put("spiderX", p.fields["spiderX"] ?: "/")
                    },
                )
            } else {
                s.put(
                    "tlsSettings",
                    JSONObject().apply {
                        put("allowInsecure", p.fields["allowInsecure"] == "true")
                        put("serverName", p.fields["sni"] ?: "")
                        p.fields["fingerprint"]?.takeIf { it.isNotEmpty() }?.let { put("fingerprint", it) }
                        p.fields["alpn"]?.takeIf { it.isNotEmpty() }?.let {
                            put("alpn", JSONArray().put(it))
                        }
                    },
                )
            }
        }
        return s
    }
}

package com.crystaln.vpn.desktop.net

import com.crystaln.vpn.data.Profile
import com.crystaln.vpn.data.Protocol
import com.crystaln.vpn.data.SettingsStore
import com.crystaln.vpn.desktop.AppDirs
import com.crystaln.vpn.data.TrafficStatsStore
import com.crystaln.vpn.xray.XrayConfigBuilder
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import java.io.File
import java.net.InetSocketAddress
import java.net.Socket

/** Active connectivity check: HTTP through the local socks inbound. */
internal fun probeThroughTunnel(url: String, socksPort: Int, timeoutSec: Int): Boolean {
    val deadline = System.currentTimeMillis() + timeoutSec * 1000L
    while (System.currentTimeMillis() < deadline) {
        try {
            val conn = java.net.URL(url).openConnection(
                java.net.Proxy(java.net.Proxy.Type.SOCKS, java.net.InetSocketAddress("127.0.0.1", socksPort)),
            ) as java.net.HttpURLConnection
            conn.connectTimeout = 4000
            conn.readTimeout = 4000
            conn.instanceFollowRedirects = false
            conn.useCaches = false
            val code = conn.responseCode
            conn.disconnect()
            if (code in 200..399) return true
        } catch (_: Throwable) {
        }
        Thread.sleep(600)
    }
    return false
}

internal fun TunnelManager.connectXray(p: Profile) {
        val dataDir = AppDirs.configDir()
        val socksPort = SettingsStore.socksPort(dataDir)
        val httpPort = SettingsStore.httpPort(dataDir)
        val opts = XrayConfigBuilder.Options(
            dnsViaTunnel = SettingsStore.dnsViaTunnel(dataDir),
            dnsServer = SettingsStore.dnsServer(dataDir),
            blockAds = SettingsStore.blockAds(dataDir),
        )
        val bin = AppDirs.binDir()
        val st = Binaries.status()
        if (!st.xrayReady) {
            throw IllegalStateException("Бинарник xray не найден — нажмите «Обновить бинарники»")
        }
        if (SettingsStore.tunnelMode(dataDir) == SettingsStore.TunnelMode.TUN &&
            !com.crystaln.vpn.desktop.Platform.supportsTun
        ) {
            throw IllegalStateException(
                "TUN-режим недоступен на " + com.crystaln.vpn.desktop.Platform.displayName +
                    ": переключите режим в «Настройки → Прокси» (SOCKS/HTTP через xray).",
            )
        }
        if (SettingsStore.tunnelMode(dataDir) == SettingsStore.TunnelMode.TUN && !st.tun2socksReady) {
            throw IllegalStateException("tun2socks не найден — нажмите «Обновить бинарники»")
        }
        if (SettingsStore.tunnelMode(dataDir) == SettingsStore.TunnelMode.TUN && !st.wintunReady) {
            throw IllegalStateException("wintun.dll не найден — нажмите «Обновить бинарники»")
        }
        if (opts.blockAds && !st.geositeReady) {
            logLine("geosite.dat отсутствует — блокировка рекламы выключена в этой сессии")
        }

        val config = XrayConfigBuilder.buildProxy(p, opts, socksPort, httpPort)
        val configFile = File(AppDirs.dataDir(), "xray-config.json")
        SecureFiles.writeText(configFile, config)

        // Hysteria2: the hysteria core (child process) must be up and serving
        // its local SOCKS before xray starts — its outbound points there.
        if (p.isHysteria) {
            HysteriaRunner.start(p)
        }
        if (p.isSingBoxFamily) {
            SingBoxRunner.start(p)
        }


        logLine("Запуск xray (${if (opts.blockAds) "с geosite" else "без geosite"})…")
        val env = mutableListOf("XRAY_LOCATION_ASSET=${bin.absolutePath}")
        xray = ChildProcess(
            "xray",
            listOf(ChildProcess.bin(bin, Binaries.XRAY), "run", "-c", configFile.absolutePath),
        ) { logLine("[xray] $it") }
        Thread.sleep(500)
        if (xray?.alive != true) {
            throw IllegalStateException("xray завершился сразу — смотрите журнал")
        }
        // Wait for the local socks listener; xray says nothing useful on stdout.
        var socksUp = false
        repeat(30) {
            socksUp = try {
                Socket().use { s -> s.connect(InetSocketAddress("127.0.0.1", socksPort), 300); true }
            } catch (_: Throwable) {
                Thread.sleep(200); false
            }
            if (socksUp) return@repeat
        }
        if (!socksUp) throw IllegalStateException("xray не открыл локальный прокси-порт")

        // Active connectivity check through the tunnel.
        if (!probeThroughTunnel(SettingsStore.checkUrl(dataDir), socksPort, SettingsStore.checkTimeoutSec(dataDir))) {
            xray?.stop()
            throw IllegalStateException("Сервер не отвечает через туннель")
        }

        val mode = SettingsStore.tunnelMode(dataDir)
        if (mode == SettingsStore.TunnelMode.PROXY) {
            markConnected(p, "proxy")
            return
        }

        // ── TUN mode ─────────────────────────────────────────────────────
        if (com.crystaln.vpn.desktop.Platform.isWindows) {
            connectTunWindows(p, socksPort)
            return
        }

        logLine("Настройка TUN-устройства (нужны права root)…")
        origGateway = defaultGateway()
        val dev = "crystaln0"
        val setup = listOf(
            "ip tuntap add mode tun dev $dev",
            "ip addr add 198.18.0.1/15 dev $dev",
            "ip link set $dev up",
            "ip route replace default dev $dev",
        )
        val res = Privileges.runScript("tun-setup", setup)
        if (res != Privileges.Result.Ok) {
            teardownTunQuietly()
            xray?.stop()
            throw IllegalStateException(
                "Не удалось настроить TUN (нужны права root): " +
                    ((res as Privileges.Result.Fail).output.ifBlank { "отказано в доступе" }),
            )
        }
        tun2socks = ChildProcess(
            "tun2socks",
            listOf(
                ChildProcess.bin(bin, Binaries.TUN2SOCKS),
                "--device", dev,
                "--proxy", "socks5://127.0.0.1:$socksPort",
                "--loglevel", "warn",
            ),
        ) { logLine("[tun2socks] $it") }
        Thread.sleep(700)
        if (tun2socks?.alive != true) {
            teardownTunQuietly()
            xray?.stop()
            throw IllegalStateException("tun2socks завершился — смотрите журнал")
        }
        markConnected(p, "tun")
    }

    // ── Windows backends ─────────────────────────────────────────────────

    /**
     * Windows TUN: tun2socks создаёт wintun-адаптер сам, поэтому он стартует
     * первым (elevated, detached), затем адаптеру назначается IP 198.18.0.1/15
     * и добавляются маршруты. IP VPN-сервера получает bypass-маршрут через
     * оригинальный шлюз — иначе туннель «проглатывает» собственный
     * транспортный трафик (анти-слуп).
     */
internal fun TunnelManager.connectTunWindows(p: Profile, socksPort: Int) {
        val bin = AppDirs.binDir()
        val exe = ChildProcess.bin(bin, Binaries.TUN2SOCKS)
        val pidFile = File(AppDirs.dataDir(), "tun2socks.pid")
        val dev = "crystaln0"
        val gw = defaultGatewayWindows()
        val serverIp = resolveAddress(p.address)
        logLine("Настройка TUN-устройства (нужны права администратора)…")
        val cmds = mutableListOf(
            // Start-Process не задаёт $LASTEXITCODE (cmdlet) — ок для прелюдии.
            "\$t2s = Start-Process -FilePath '$exe' -ArgumentList " +
                "'-device','$dev','-proxy','socks5://127.0.0.1:$socksPort','-loglevel','warn' " +
                "-WindowStyle Hidden -PassThru; \$t2s.Id | Set-Content '${pidFile.absolutePath}'",
            waitForAdapterCommand(dev, tries = 60, pauseMs = 500),
            "netsh interface ip set address name=\"$dev\" source=static " +
                "addr=198.18.0.1 mask=255.254.0.0",
        )
        if (serverIp != null && gw != null) {
            cmds += "route add $serverIp mask 255.255.255.255 ${gw.first} metric 1 if ${gw.second}"
        } else {
            logLine("Не удалось определить IP сервера или шлюз — bypass-маршрут не добавлен")
        }
        cmds += "route add 0.0.0.0 mask 0.0.0.0 198.18.0.1 metric 1"
        val res = Privileges.runScript("tun-setup-win", cmds)
        if (res != Privileges.Result.Ok) {
            // tun2socks уже мог успеть стартовать — тихо убираем.
            Privileges.runScript("tun-cleanup-win", listOf(killPidCommand(pidFile)))
            throw IllegalStateException(
                "Не удалось настроить TUN (нужны права администратора): " +
                    ((res as Privileges.Result.Fail).output.ifBlank { "отказано в доступе" }),
            )
        }
        tun2socksPidFile = pidFile
        tunServerIp = serverIp
        origGateway = gw?.first
        origIfIndex = gw?.second
        markConnected(p, "tun")
    }

    /**
     * WireGuard/AWG на Windows: amneziawg.exe устанавливает туннель как
     * Windows-сервис (SYSTEM). Сервис сам создаёт wintun-адаптер, применяет
     * Address/DNS/MTU (wg-quick-семантика) и маршруты AllowedIPs, включая
     * bypass-маршрут до endpoint. Один бинарник обслуживает и plain WireGuard,
     * и AmneziaWG (junk-параметры I1..I5).
     */
internal fun TunnelManager.connectWgService(p: Profile, mode: String) {
        if (p.wgConfig.isBlank()) {
            throw IllegalStateException(
                "В профиле нет конфигурации ${if (mode == "awg") "AmneziaWG" else "WireGuard"}",
            )
        }
        if (!Binaries.status().awgReady) {
            throw IllegalStateException(
                "Бинарники AmneziaWG не найдены — Настройки → Система → «Обновить бинарники»",
            )
        }
        val parsed = WgSetconf.build(p.wgConfig, p.fields)
        val iface = ifaceName(p)
        val confFile = File(File(AppDirs.dataDir(), "tunnels"), "$iface.conf")
        confFile.parentFile?.mkdirs()
        SecureFiles.writeText(confFile, buildServiceConf(parsed))
        val exe = File(AppDirs.binDir(), "${Binaries.AWG_SERVICE}.exe").absolutePath
        logLine("Подключение ${if (mode == "awg") "AmneziaWG" else "WireGuard"} ($iface)…")
        val cmds = listOf(
            // Фоновая чистка застрявшего старого сервиса; не должна фейлить скрипт.
            "& '$exe' /uninstalltunnelservice $iface | Out-Null; \$LASTEXITCODE = 0",
            "& '$exe' /installtunnelservice '${confFile.absolutePath}'",
            // Сервис появляется асинхронно: ждём адаптер с именем туннеля.
            waitForAdapterCommand(iface, tries = 150, pauseMs = 400),
        )
        val res = Privileges.runScript("wg-service-up", cmds)
        if (res != Privileges.Result.Ok) {
            Privileges.runScript(
                "wg-service-cleanup",
                listOf("& '$exe' /uninstalltunnelservice $iface | Out-Null; \$LASTEXITCODE = 0"),
            )
            throw IllegalStateException(
                "Не удалось установить туннель $iface: " +
                    ((res as Privileges.Result.Fail).output.ifBlank { "отказано в доступе" }),
            )
        }
        wgService = iface
        markConnected(p, mode)
    }

    /**
     * wg-quick-style конфиг для amneziawg.exe /installtunnelservice: [Interface]
     * дополняется Address/DNS/MTU (их setconf-формат выносит отдельно).
     */
private fun buildServiceConf(parsed: WgSetconf.Result): String {
        if (parsed.addresses.isEmpty()) {
            throw IllegalStateException("В конфигурации нет Address — адаптеру нечего назначить")
        }
        val head = "[Interface]\n"
        val rest = parsed.setconf.removePrefix(head)
        return buildString {
            append(head)
            append("Address = ").appendLine(parsed.addresses.joinToString(", "))
            if (parsed.dnsServers.isNotEmpty()) {
                append("DNS = ").appendLine(parsed.dnsServers.joinToString(", "))
            }
            append("MTU = ").appendLine(parsed.mtu.toString())
            append(rest)
        }
    }

internal fun TunnelManager.connectOpenVpnWindows(p: Profile) {
        val exe = Binaries.openVpnExecutable()
        if (!exe.exists()) {
            throw IllegalStateException(
                "openvpn не найден — Настройки → Система → «Обновить бинарники»",
            )
        }
        val conf = p.ovpnConfig.ifBlank {
            throw IllegalStateException("В профиле нет конфигурации OpenVPN")
        }
        val dir = File(AppDirs.dataDir(), "tunnels")
        dir.mkdirs()
        val base = "openvpn-" + p.id.lowercase().map {
            if (it in 'a'..'z' || it in '0'..'9' || it == '-' || it == '_') it else 'x'
        }.joinToString("").take(8).ifEmpty { "0" }
        val confFile = File(dir, "$base.ovpn").apply { writeText(conf) }
        val user = p.fields["ovpnUser"]?.trim().orEmpty()
        val pass = p.fields["ovpnPass"]?.trim().orEmpty()
        val authFile = openVpnCredentialText(user, pass)?.let {
            File(dir, "$base.auth").apply { SecureFiles.writeText(this, it) }
        }
        val logFile = File(dir, "$base.log")
        val pidFile = File(dir, "$base.pid")
        logLine("Запуск openvpn…")
        val args = mutableListOf(
            "--config", "\"${confFile.absolutePath}\"",
            "--dev", "crystaln0",
            "--windows-driver", "wintun",
            "--log", "\"${logFile.absolutePath}\"",
        )
        if (authFile != null) args += listOf("--auth-user-pass", "\"${authFile.absolutePath}\"")
        val cmds = listOf(
            "\$o = Start-Process -FilePath '${exe.absolutePath}' -ArgumentList " +
                args.joinToString(",") { "'$it'" } +
                " -WindowStyle Hidden -PassThru; \$o.Id | Set-Content '${pidFile.absolutePath}'",
            // Адаптер появляется при успешном подъёме туннеля.
            waitForAdapterCommand("crystaln0", tries = 100, pauseMs = 500),
            // Адаптер может остаться от прошлого подключения — проверяем сам
            // процесс: если он умер (ошибка аутентификации/конфига), показываем
            // его лог.
            "if (-not (Get-Process -Id (Get-Content '${pidFile.absolutePath}') " +
                "-ErrorAction SilentlyContinue)) { " +
                "Get-Content '${logFile.absolutePath}' -Tail 15 -ErrorAction SilentlyContinue; exit 1 }",
        )
        val res = Privileges.runScript("ovpn-up-win", cmds)
        if (res != Privileges.Result.Ok) {
            Privileges.runScript("ovpn-cleanup-win", listOf(killPidCommand(pidFile)))
            confFile.delete()
            authFile?.delete()
            logFile.delete()
            pidFile.delete()
            throw IllegalStateException(
                "openvpn не запущен: " +
                    ((res as Privileges.Result.Fail).output.ifBlank { "смотрите журнал" }),
            )
        }
        openvpnFiles = listOfNotNull(confFile, authFile, logFile, pidFile)
        openvpnPidFile = pidFile
        markConnected(p, "openvpn")
    }

    /** PowerShell-цикл ожидания wintun-адаптера; exit 1 при таймауте. */
private fun waitForAdapterCommand(name: String, tries: Int, pauseMs: Int): String =
        "\$ok=\$false; foreach(\$i in 1..$tries){ " +
            "if (Get-NetAdapter -Name '$name' -ErrorAction SilentlyContinue) { \$ok=\$true; break }; " +
            "Start-Sleep -Milliseconds $pauseMs }; if (-not \$ok) { exit 1 }"

    /** Убивает процесс по pid-файлу; строка не должна фейлить скрипт. */
private fun killPidCommand(pidFile: File): String =
        "if (Test-Path '${pidFile.absolutePath}') { " +
            "\$p = Get-Content '${pidFile.absolutePath}' -ErrorAction SilentlyContinue; " +
            "if (\$p) { Get-Process -Id \$p -ErrorAction SilentlyContinue | Stop-Process -Force }; " +
            "Remove-Item '${pidFile.absolutePath}' -Force -ErrorAction SilentlyContinue }"

    /** Шлюз и индекс интерфейса основного маршрута Windows, null если нет. */
private fun defaultGatewayWindows(): Pair<String, Int>? {
        return try {
            val ps = ProcessBuilder(
                "powershell", "-NoProfile", "-NonInteractive", "-Command",
                "Get-NetRoute -DestinationPrefix 0.0.0.0/0 -ErrorAction SilentlyContinue | " +
                    "Sort-Object RouteMetric | Select-Object -First 1 | " +
                    "ForEach-Object { \"{0}|{1}\" -f \$_.NextHop, \$_.InterfaceIndex }",
            ).apply { redirectErrorStream(true) }.start()
            val out = ps.inputStream.readBytes().toString(Charsets.UTF_8).trim()
            ps.waitFor()
            val line = out.lineSequence().firstOrNull { it.isNotBlank() } ?: return null
            val parts = line.split('|')
            if (parts.size != 2) return null
            val gw = parts[0].trim()
            val idx = parts[1].trim().toIntOrNull()
            // NextHop 0.0.0.0 = on-link маршрут, через него bypass не построить.
            if (idx != null && gw.isNotEmpty() && gw != "0.0.0.0") gw to idx else null
        } catch (_: Throwable) {
            null
        }
    }

    /** Резолвит адрес сервера (для bypass-маршрута); null при неудаче. */
private fun resolveAddress(host: String?): String? = try {
        host?.trim()?.takeIf { it.isNotEmpty() }
            ?.let { java.net.InetAddress.getAllByName(it).firstOrNull()?.hostAddress }
    } catch (_: Throwable) {
        null
    }

internal fun TunnelManager.connectWireGuard(p: Profile) {
        if (com.crystaln.vpn.desktop.Platform.isWindows) {
            connectWgService(p, "wg")
            return
        }
        requireDaemons()
        if (!ChildProcess.commandExists("wg-quick")) {
            if (Binaries.status().awgReady) {
                logLine("wg-quick не установлен — использую amneziawg-go в режиме WireGuard…")
                connectAwgBackend(p, "wg")
                return
            }
            throw IllegalStateException(
                "wg-quick не установлен (пакет wireguard-tools) и нет amneziawg-go — нажмите «Обновить бинарники»",
            )
        }
        val conf = p.wgConfig.ifBlank {
            throw IllegalStateException("В профиле нет конфигурации WireGuard")
        }
        val name = ifaceName(p)
        val path = "/etc/wireguard/$name.conf"
        logLine("Подключение wg-quick ($name)…")
        // wg-quick needs the config file inside /etc/wireguard with strict perms.
        val tmp = File.createTempFile(name, ".conf")
        SecureFiles.writeText(tmp, conf)
        tmp.setReadable(false, false)
        tmp.setReadable(true, true)
        val setup = listOf(
            "install -m 600 $tmp ${path.replace("\'", "\\'")}",
            "wg-quick up $name",
        )
        val res = Privileges.runScript("wg-up", setup)
        tmp.delete()
        if (res != Privileges.Result.Ok) {
            throw IllegalStateException(
                "wg-quick up не выполнен: " + ((res as Privileges.Result.Fail).output.ifBlank { "отказано в доступе" }),
            )
        }
        wgConfPath = path
        markConnected(p, "wg")
    }

internal fun TunnelManager.connectAmneziaWg(p: Profile) {
        requireDaemons()
        connectAwgBackend(p, "awg")
    }

    /** Userspace WireGuard-compatible backend used by AWG and as a wg-quick fallback. */
internal fun TunnelManager.connectAwgBackend(p: Profile, mode: String) {
        if (com.crystaln.vpn.desktop.Platform.isWindows) {
            // Windows: amneziawg.exe tunnel service, plain WG и AWG одним бинарем.
            connectWgService(p, mode)
            return
        }
        if (!Binaries.status().awgReady) {
            throw IllegalStateException(
                "Бинарники AmneziaWG не найдены — Настройки → Система → «Обновить бинарники»",
            )
        }
        if (p.wgConfig.isBlank()) {
            throw IllegalStateException("В профиле нет конфигурации ${if (mode == "awg") "AmneziaWG" else "WireGuard"}")
        }
        val parsed = WgSetconf.build(p.wgConfig, p.fields)
        val iface = ifaceName(p)
        val bin = AppDirs.binDir()
        val goBin = ChildProcess.bin(bin, Binaries.AWG_GO)
        val awgBin = ChildProcess.bin(bin, Binaries.AWG)
        val pidFile = File(AppDirs.dataDir(), "amneziawg.pid")
        val confFile = "/var/run/amneziawg/$iface.conf"
        val socket = "/var/run/amneziawg/$iface.sock"
        // Лог демона нужен для диагностики: без него причина падения
        // amneziawg-go невидима (вывод больше не идёт в /dev/null).
        val logFile = "/var/run/amneziawg/$iface.log"
        val tmp = File.createTempFile(iface, ".conf")
        SecureFiles.writeText(tmp, parsed.setconf)
        tmp.setReadable(false, false)
        tmp.setReadable(true, true)
        logLine("Запуск amneziawg-go ($iface)…")
        val cmds = mutableListOf(
            "mkdir -p /var/run/amneziawg",
            "rm -f $confFile $socket ${pidFile.absolutePath}",
            "install -m 600 ${tmp.absolutePath} $confFile",
            // -f is important: without it amneziawg-go re-execs itself and $!
            // would point at the short-lived parent, not the actual daemon.
            // CRYSTALN_DEBUG=1 включает подробный лог amneziawg-go (диагностика
            // хендшейков). По умолчанию — только ошибки, чтобы лог не рос.
            "LOG_LEVEL=\${CRYSTALN_DEBUG:+debug} nohup $goBin -f $iface >\"$logFile\" 2>&1 & echo \$! > ${pidFile.absolutePath}",
            "for i in $(seq 1 100); do [ -S $socket ] && break; sleep 0.1; done",
            // Если сокет не появился — процесс мёртв или завис; показываем его лог,
            // иначе пользователь видит только вторичную ошибку kill.
            "[ -S $socket ] || { kill $(cat ${pidFile.absolutePath}) 2>/dev/null; tail -n 10 \"$logFile\" 2>/dev/null; exit 1; }",
            "$awgBin setconf $iface $confFile",
            "ip link set $iface mtu ${parsed.mtu} up",
        )
        parsed.addresses.forEach { cmds += "ip address add $it dev $iface" }
        if (parsed.defaultRoute) {
            // Same routing model as wg-quick: tunnel packets for ordinary
            // traffic, but leave the server's route in the main table.
            cmds += listOf(
                "$awgBin set $iface fwmark 51820",
                "ip -4 rule add not fwmark 51820 table 51820 || true",
                "ip -4 rule add table main suppress_prefixlength 0 || true",
                "ip -6 rule add not fwmark 51820 table 51820 || true",
                "ip -6 rule add table main suppress_prefixlength 0 || true",
            )
            if ("0.0.0.0/0" in parsed.routes) {
                cmds += "ip -4 route add 0.0.0.0/0 dev $iface table 51820 || true"
            }
            if ("::/0" in parsed.routes) {
                cmds += "ip -6 route add ::/0 dev $iface table 51820 || true"
            }
        }
        parsed.routes.filter { it != "0.0.0.0/0" && it != "::/0" }.forEach {
            cmds += "ip route replace $it dev $iface"
        }
        if (parsed.dnsServers.isNotEmpty()) {
            // Все запросы (включая заблокированные домены, которые провайдер
            // подменяет) должны идти в DNS туннеля, а не в DNS роутера.
            cmds += "resolvectl dns $iface ${parsed.dnsServers.joinToString(" ")} || true"
            cmds += "resolvectl domain $iface '~.' || true"
            cmds += "resolvectl default-route $iface yes || true"
            cmds += "resolvectl flush-caches || true"
        }
        val res = Privileges.runScript("awg-up", cmds)
        tmp.delete()
        if (res != Privileges.Result.Ok) {
            Privileges.runScript("awg-failed", awgDownCommands(iface, pidFile, confFile, socket))
            throw IllegalStateException(
                "amneziawg-go не запущен: " +
                    ((res as Privileges.Result.Fail).output.ifBlank { "отказано в доступе" }),
            )
        }
        awgIface = iface
        markConnected(p, mode)
    }

private fun awgDownCommands(iface: String, pidFile: File, confFile: String, socket: String) = listOf(
        "kill $(cat ${pidFile.absolutePath}) || true",
        "rm -f ${pidFile.absolutePath}",
        "ip -4 rule del table main suppress_prefixlength 0 || true",
        "ip -4 rule del not fwmark 51820 table 51820 || true",
        "ip -6 rule del table main suppress_prefixlength 0 || true",
        "ip -6 rule del not fwmark 51820 table 51820 || true",
        "ip route flush table 51820 || true",
        "ip link del $iface || true",
        "resolvectl revert $iface || true",
        "rm -f $confFile $socket",
    )

internal fun TunnelManager.connectOpenVpn(p: Profile) {
        if (com.crystaln.vpn.desktop.Platform.isWindows) {
            connectOpenVpnWindows(p)
            return
        }
        requireDaemons()
        if (!ChildProcess.commandExists("openvpn")) {
            throw IllegalStateException("openvpn не найден в системе")
        }
        val conf = p.ovpnConfig.ifBlank {
            throw IllegalStateException("В профиле нет конфигурации OpenVPN")
        }
        val file = File.createTempFile("crystaln-", ".ovpn")
        SecureFiles.writeText(file, conf)
        // OpenVPN runs as root and reads these files before dropping privileges.
        // Keep secrets owner-readable on disk, even before pkexec starts it.
        file.setReadable(false, false)
        file.setReadable(true, true)
        file.setWritable(false, false)
        file.setWritable(true, true)
        val user = p.fields["ovpnUser"]?.trim().orEmpty()
        val pass = p.fields["ovpnPass"]?.trim().orEmpty()
        val authFile = openVpnCredentialText(user, pass)?.let { credentials ->
            File.createTempFile("crystaln-", ".auth").apply {
                SecureFiles.writeText(this, credentials)
            }
        }
        logLine("Запуск openvpn…")
        // openvpn must run privileged to create the TUN; run it detached via
        // pkexec/sudo and supervise its lifecycle through a pidfile.
        val pidFile = File(AppDirs.dataDir(), "openvpn.pid")
        val script = listOf(
            "rm -f ${pidFile.absolutePath}",
            "sh -c 'openvpn --config ${file.absolutePath.replace("\'", "\\'")} " +
                (authFile?.let { "--auth-user-pass ${it.absolutePath} " } ?: "") +
                "--dev crystaln0 --script-security 2 & echo \$! > ${pidFile.absolutePath}'",
        )
        val res = Privileges.runScript("ovpn-up", script)
        if (res != Privileges.Result.Ok) {
            file.delete()
            authFile?.delete()
            throw IllegalStateException(
                "openvpn не запущен: " + ((res as Privileges.Result.Fail).output.ifBlank { "отказано в доступе" }),
            )
        }
        openvpnFiles = listOfNotNull(file, authFile)
        openvpn = ChildProcess(
            "openvpn-watch",
            listOf("sh", "-c", "while kill -0 $(cat ${pidFile.absolutePath}) 2>/dev/null; do sleep 1; done"),
        ) { /* watcher is silent; openvpn output went to the elevated session */ }
        markConnected(p, "openvpn")
    }

internal fun TunnelManager.teardownAll() {
        polling = false
        if (com.crystaln.vpn.desktop.Platform.isWindows) WindowsHelper.stopStatsPoller()
        val mode = _ui.value.mode
        var stoppedSomething = false
        when (mode) {
            "wg" -> {
                if (com.crystaln.vpn.desktop.Platform.isWindows) {
                    if (teardownWgServiceWindows()) stoppedSomething = true
                } else {
                    wgConfPath?.let { path ->
                        val name = path.substringAfterLast('/').removeSuffix(".conf")
                        Privileges.runScript("wg-down", listOf("wg-quick down $name", "rm -f $path"))
                        stoppedSomething = true
                    }
                    wgConfPath = null
                    if (teardownAwgTunnel()) stoppedSomething = true
                }
            }
            "awg" -> {
                if (com.crystaln.vpn.desktop.Platform.isWindows) {
                    if (teardownWgServiceWindows()) stoppedSomething = true
                } else if (teardownAwgTunnel()) stoppedSomething = true
            }
            "openvpn" -> {
                if (com.crystaln.vpn.desktop.Platform.isWindows) {
                    openvpnPidFile?.let { pid ->
                        Privileges.runScript("ovpn-down-win", listOf(killPidCommand(pid)))
                    }
                    stoppedSomething = true
                } else {
                    val pidFile = File(AppDirs.dataDir(), "openvpn.pid")
                    Privileges.runScript("ovpn-down", listOf("kill $(cat ${pidFile.absolutePath})", "rm -f ${pidFile.absolutePath}"))
                    openvpn?.stop()
                    openvpn = null
                    stoppedSomething = true
                }
                openvpnFiles.forEach { it.delete() }
                openvpnFiles = emptyList()
                openvpnPidFile = null
            }
            "tun" -> {
                if (com.crystaln.vpn.desktop.Platform.isWindows) {
                    teardownTunWindows()
                } else {
                    tun2socks?.stop()
                    tun2socks = null
                    teardownTunQuietly()
                }
                stoppedSomething = true
            }
        }
        if (xray != null) stoppedSomething = true
        xray?.stop()
        xray = null
        HysteriaRunner.stop()
        HysteriaRunner.stop()
        SingBoxRunner.stop()
        if (stoppedSomething) logLine("Туннель остановлен")
    }

private fun TunnelManager.teardownAwgTunnel(): Boolean {
        val iface = awgIface ?: return false
        Privileges.runScript(
            "awg-down",
            awgDownCommands(
                iface,
                File(AppDirs.dataDir(), "amneziawg.pid"),
                "/var/run/amneziawg/$iface.conf",
                "/var/run/amneziawg/$iface.sock",
            ),
        )
        awgIface = null
        return true
    }

private fun TunnelManager.teardownTunQuietly() {
        val dev = "crystaln0"
        val cmds = mutableListOf<String>()
        origGateway?.let { gw -> cmds += "ip route replace default via $gw" }
        cmds += "ip link del $dev"
        Privileges.runScript("tun-down", cmds)
        origGateway = null
    }

    /** Windows TUN teardown: убить tun2socks, снять маршруты (адаптер умирает с ним). */
private fun TunnelManager.teardownTunWindows() {
        val cmds = mutableListOf(
            killPidCommand(tun2socksPidFile ?: File(AppDirs.dataDir(), "tun2socks.pid")),
            // Снять наши маршруты; несуществующие (адаптер уже умер) — не ошибка.
            "route delete 0.0.0.0 mask 0.0.0.0 198.18.0.1 2>\$null; \$LASTEXITCODE = 0",
        )
        tunServerIp?.let { ip ->
            cmds += "route delete $ip mask 255.255.255.255 2>\$null; \$LASTEXITCODE = 0"
        }
        Privileges.runScript("tun-down-win", cmds)
        tun2socksPidFile = null
        tunServerIp = null
        origGateway = null
        origIfIndex = null
    }

    /** Windows: снять amneziawg tunnel service и удалить конфиг. */
private fun TunnelManager.teardownWgServiceWindows(): Boolean {
        val iface = wgService ?: return false
        val exe = File(AppDirs.binDir(), "${Binaries.AWG_SERVICE}.exe").absolutePath
        Privileges.runScript(
            "wg-service-down",
            listOf("& '$exe' /uninstalltunnelservice $iface | Out-Null; \$LASTEXITCODE = 0"),
        )
        File(File(AppDirs.dataDir(), "tunnels"), "$iface.conf").delete()
        wgService = null
        return true
    }

/** openvpn's auth-user-pass file has one unescaped username/password per line. */
internal fun openVpnCredentialText(user: String?, pass: String?): String? {
    val u = user?.trim().orEmpty()
    val p = pass?.trim().orEmpty()
    return if (u.isEmpty() && p.isEmpty()) null else "$u\n$p\n"
}
internal fun TunnelManager.connectSingBox(p: Profile) {
    val dataDir = AppDirs.configDir()
    val socksPort = SettingsStore.socksPort(dataDir)
    val httpPort = SettingsStore.httpPort(dataDir)
    val opts = XrayConfigBuilder.Options(
        dnsViaTunnel = SettingsStore.dnsViaTunnel(dataDir),
        dnsServer = SettingsStore.dnsServer(dataDir),
        blockAds = SettingsStore.blockAds(dataDir),
    )
    val bin = AppDirs.binDir()
    val st = Binaries.status()
    if (!st.xrayReady) throw IllegalStateException("xray not found")
    if (!st.singboxReady) throw IllegalStateException("sing-box not found")
    if (SettingsStore.tunnelMode(dataDir) == SettingsStore.TunnelMode.TUN && !st.tun2socksReady) {
        throw IllegalStateException("tun2socks not found")
    }
    if (SettingsStore.tunnelMode(dataDir) == SettingsStore.TunnelMode.TUN && !st.wintunReady) {
        throw IllegalStateException("wintun not found")
    }
    SingBoxRunner.start(p)
    val config = XrayConfigBuilder.buildProxy(p, opts, socksPort, httpPort)
    val configFile = File(AppDirs.dataDir(), "xray-config.json")
    SecureFiles.writeText(configFile, config)
    xray = ChildProcess(
        "xray",
        listOf(ChildProcess.bin(bin, Binaries.XRAY), "run", "-c", configFile.absolutePath),
    ) { logLine("[xray] $it") }
    Thread.sleep(500)
    if (xray?.alive != true) {
        SingBoxRunner.stop()
        throw IllegalStateException("xray exited immediately")
    }
    var socksUp = false
    repeat(30) {
        socksUp = try { Socket().use { s -> s.connect(InetSocketAddress("127.0.0.1", socksPort), 300); true } } catch (_: Throwable) { Thread.sleep(200); false }
        if (socksUp) return@repeat
    }
    if (!socksUp) { SingBoxRunner.stop(); xray?.stop(); throw IllegalStateException("xray proxy port not opened") }
    val mode = SettingsStore.tunnelMode(dataDir)
    if (mode == SettingsStore.TunnelMode.PROXY) { markConnected(p, "proxy"); return }
    if (com.crystaln.vpn.desktop.Platform.isWindows) {
        SingBoxRunner.stop(); xray?.stop(); throw IllegalStateException("TUN mode for sing-box on Windows not supported yet - use proxy mode")
    }
    origGateway = defaultGateway()
    val dev = "crystaln0"
    val setup = listOf("ip tuntap add mode tun dev $dev", "ip addr add 198.18.0.1/15 dev $dev", "ip link set $dev up", "ip route replace default dev $dev")
    val res = Privileges.runScript("tun-setup", setup)
    if (res != Privileges.Result.Ok) {
        teardownTunQuietly(); xray?.stop(); SingBoxRunner.stop()
        throw IllegalStateException("TUN setup failed")
    }
    tun2socks = ChildProcess("tun2socks", listOf(ChildProcess.bin(bin, Binaries.TUN2SOCKS), "--device", dev, "--proxy", "socks5://127.0.0.1:$socksPort", "--loglevel", "warn")) { logLine("[tun2socks] $it") }
    Thread.sleep(700)
    if (tun2socks?.alive != true) {
        teardownTunQuietly(); xray?.stop(); SingBoxRunner.stop()
        throw IllegalStateException("tun2socks exited")
    }
    markConnected(p, "tun")
}
